  li_santuario: ['lia', 'Estatuetas cobertas de musgo no meio da floresta. Pedras-memória pequenas, de perdas recentes. Alguém deixou flores frescas aqui. Hoje.', 'tender'],
  li_banco: ['lia', 'Um banco virado pro oeste. Quem colocou ele aqui sabia exatamente onde o sol se põe.', 'neutral'],
