  li_sentar4: ['lia', 'O sol esquenta a pedra. Dá pra sentir na mão.', 'tender'],
  li_mapa_cheio: ['lia', 'Oito lugares. Oito pedaços da mesma família. Só falta a Odessa.', 'tender'],
  li_estrela: ['lia', 'Uma estrela cadente. Dizem que é pra pedir alguma coisa. Não me ocorreu nada.', 'neutral'],
  li_estrela2: ['lia', 'Outra! Essa eu vi inteira.', 'happy'],
